#include "military_station_original_sources.hpp"
#include "hanmo/resident_world_api.hpp"
#include <set>
namespace hanmo::resident {using namespace movement_detail;using namespace duty_detail;namespace {
void registration(const ActionTimeRegistration& r){const auto e=military_station_action_time_registration();if(r.action_kind!=e.action_kind||r.owner_domain!=e.owner_domain||r.profile_id!=e.profile_id||r.profile_version!=e.profile_version||r.source_schema!=e.source_schema||r.mode!=e.mode||r.remaining_meaning!=e.remaining_meaning||r.shared_gate_kind||!r.retained_wait_phases.empty())fail("MilitaryStationTimeRegistrationMismatch");}
void proof_equal(const ActionTimeOwnerProof& a,const ActionTimeOwnerProof& b){if(a.action_ref!=b.action_ref||a.action_kind!=b.action_kind||a.actor_id!=b.actor_id||a.participant_actor_ids!=b.participant_actor_ids||a.phase!=b.phase||!same_source(a.original_execution_source,b.original_execution_source)||a.source_schema!=b.source_schema||a.terminal_result_ref!=b.terminal_result_ref)fail("StaleMilitaryStationActionProof",a.action_ref);}
}
ActionTimeRegistration military_station_action_time_registration(){return {"military_station","military","military_duty_presence",2,1,ActionTimeMode::service_window,ActionRemainingMeaning::authorization_window,{},{}};}
NativeMilitaryStationActionTimeRead::NativeMilitaryStationActionTimeRead(const CommonStore& common,const MilitaryDutyState& state,const MilitaryDutyContext& context):common_(common),state_(state),context_(context){}
Status NativeMilitaryStationActionTimeRead::enumerate_action_time_owners(const ActionTimeRegistration& r,ActionTimeOwnerIdSink& output)const{return status([&]{registration(r);std::set<std::string_view,std::less<>,CheckpointAllocator<std::string_view>> seen;for(const auto& row:state_.station_sources.rows()){const auto& id=row.second.actual_action.id;if(!seen.insert(id).second)fail("DuplicateMilitaryStationAction",id);take(read_action_time_owner(r,id));take(output.append(id));}});}
Outcome<ActionTimeOwnerProof> NativeMilitaryStationActionTimeRead::read_action_time_owner(const ActionTimeRegistration& r,const StableId& action)const{return guard<ActionTimeOwnerProof>([&]{registration(r);const auto actual=read_military_station_original_association(common_,state_,action);const auto& source=actual.source;const auto& t=actual.accepted_terms;const auto* accepted=&actual.accepted_source;take(context_.original.validate_accepted_terms(t,*accepted));CheckpointVector<std::string_view> members,empty;members.reserve(source.actual_action.participants.size());for(const auto& member:source.actual_action.participants)members.push_back(member);const auto original_source=SourceRefBuildView{"military","military_station_source",source.id};ActionTimeOwnerProofBuildView out{action,"military_station",source.actual_action.actor_id,{members},original_source,1,MomentOwnerSourceBuildView{original_source,1},ActionTimeOwnerPhase::working,{},{},{},{empty},{}};if(const auto* end=terminal(state_,source.id)){const auto* h=common_.state().facts.find(end->id);if(!h||h->domain!="military"||h->kind!="military_station_terminal"||take(compare_world_moments(end->ended_at,source.started_at,context_.budget))<0||(end->authorization_expired&&!same_moment(end->ended_at,until(t,context_.budget),context_.budget)))fail("MilitaryStationTerminalMismatch",action);if(end->authorization_expired&&(end->original_cause.source_schema!=1||!same_source(end->original_cause.source_ref,ref("military_duty_terms",accepted->id))))fail("MilitaryStationExpiryTermsMismatch",action);if(!end->authorization_expired&&!same_moment(source_moment(state_,context_,end->original_cause),end->ended_at,context_.budget))fail("MilitaryStationTerminationCauseMismatch",action);require_military_station_action_released(common_,action);out.phase=ActionTimeOwnerPhase::terminal;out.ended_source=MomentOwnerSourceBuildView{{"military","military_station_terminal",end->id},1};out.terminal_result_ref=end->id;}else{out.phase=read_military_station_current_action_phase(common_,source,t,action);}return ActionTimeOwnerProof(out);});}
Outcome<WorldMoment> NativeMilitaryStationActionTimeRead::read_action_time_source(const ElapsedTimeSource& source)const{return guard<WorldMoment>([&]{const auto* actual=std::get_if<MomentOwnerSource>(&source);if(!actual||actual->source_schema!=1||actual->source_ref.domain!="military")fail("MilitaryStationOriginalTimeSourceRequired");if(actual->source_ref.kind=="military_station_source"){const auto* s=state_.station_sources.find(actual->source_ref.id);if(!s)fail("MilitaryStationActionSourceRequired");return s->started_at;}if(actual->source_ref.kind=="military_station_terminal"){const auto* e=state_.station_terminals.find(actual->source_ref.id);if(!e)fail("MilitaryStationTerminalRequired");return e->ended_at;}if(actual->source_ref.kind=="military_duty_terms"){const auto* t=state_.accepted_sources.find(actual->source_ref.id);if(!t)fail("MilitaryDutyAcceptedSourceRequired");return t->accepted_at;}fail("MilitaryStationOriginalTimeSourceRequired");});}
Status NativeMilitaryStationActionTimeRead::validate_fixed_action_sources(const ActionTimeRegistration&,const ActionTimeOwnerProof&,const ActionElapsedState&,const std::vector<FixedServiceTransition>&)const{return common_failure("MilitaryStationHasNoFixedElapsed");}
Status NativeMilitaryStationActionTimeRead::validate_shared_action_sources(const ActionTimeRegistration&,const ActionTimeOwnerProof&,const SharedWorkElapsedState&)const{return common_failure("MilitaryStationHasNoSharedWorkGate");}
Outcome<RunStop> NativeMilitaryStationActionTimeRead::read_action_continuation_stop(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const WorldMoment& now)const{return guard<RunStop>([&]{const auto actual=take(read_action_time_owner(r,supplied.action_ref));proof_equal(supplied,actual);const auto& source=military_station_source_for_action(state_,actual.action_ref);if(const auto* end=terminal(state_,source.id)){if(take(compare_world_moments(end->ended_at,now,context_.budget))>0)fail("MilitaryStationFutureTerminal");return end->authorization_expired?RunStop::completed:RunStop::cancelled;}if(actual.phase==ActionTimeOwnerPhase::suspended)return RunStop::paused;const auto& t=terms(state_,source.duty_action_id);if(take(compare_world_moments(now,until(t,context_.budget),context_.budget))>=0)fail("MilitaryStationUnconsumedAuthorizationExpiry");take(context_.original.validate_execution_binding(t,now));return RunStop::budget_exhausted;});}
Outcome<OriginalActionRemaining> NativeMilitaryStationActionTimeRead::read_original_action_remaining(const ActionTimeRegistration& r,const ActionTimeOwnerProof& supplied,const WorldMoment&)const{return guard<OriginalActionRemaining>([&]()->OriginalActionRemaining{const auto actual=take(read_action_time_owner(r,supplied.action_ref));proof_equal(supplied,actual);const auto& t=terms(state_,military_station_source_for_action(state_,actual.action_ref).duty_action_id);const auto* e=state_.executions.find(t.duty_action_id);if(!e)fail("MilitaryDutyExecutionRequired");return ActualAuthorizationRemaining{ActualAuthorizationRemainingBuildView{t.until_tick,{"military","military_duty_terms",e->accepted_source_ref},1}};});}
Outcome<StableId> NativeMilitaryStationActionTimeRead::read_gate_result_id(const SharedWorkGateResult&)const{return {false,{},common_failure("MilitaryStationHasNoSharedWorkGate").error};}
Outcome<SharedWorkGateResult> NativeMilitaryStationActionTimeRead::read_original_gate_result(const StableId&)const{return {false,{},common_failure("MilitaryStationHasNoSharedWorkGate").error};}
Status NativeMilitaryStationActionTimeRead::validate_original_gate_result(const SharedWorkGateResult&)const{return common_failure("MilitaryStationHasNoSharedWorkGate");}
}
